description:
Write `struct Timeline` that stores named events at times (minutes since midnight, `u32`) in a `BTreeMap<u32, Vec<String>>`:

- `new()`, `add(&mut self, time: u32, name: &str)` (several events may share a time; they keep the order they were added);
- `between(&self, from: u32, to: u32) -> Vec<(u32, String)>`: events with `from <= time < to`, in time order;
- `next_after(&self, time: u32) -> Option<(u32, String)>`: the first event strictly after `time` (the first added, at that time);
- `remove_before(&mut self, time: u32) -> usize`: removes every event before `time` and returns how many;
- `busiest(&self) -> Option<u32>`: the time with the most events (the earliest on a tie).

starter.solution.rs:
use std::collections::BTreeMap;

struct Timeline {
    events: BTreeMap<u32, Vec<String>>,
}

solution.solution.rs:
use std::collections::BTreeMap;

struct Timeline {
    events: BTreeMap<u32, Vec<String>>,
}

impl Timeline {
    fn new() -> Self {
        Timeline { events: BTreeMap::new() }
    }

    fn add(&mut self, time: u32, name: &str) {
        self.events.entry(time).or_default().push(name.to_string());
    }

    fn between(&self, from: u32, to: u32) -> Vec<(u32, String)> {
        if from >= to {
            return Vec::new();
        }
        self.events
            .range(from..to)
            .flat_map(|(&t, names)| names.iter().map(move |n| (t, n.clone())))
            .collect()
    }

    fn next_after(&self, time: u32) -> Option<(u32, String)> {
        let start = time.checked_add(1)?;              // nothing can come after u32::MAX
        self.events.range(start..).next().map(|(&t, names)| (t, names[0].clone()))
    }

    fn remove_before(&mut self, time: u32) -> usize {
        let keep = self.events.split_off(&time);
        let removed = self.events.values().map(Vec::len).sum();
        self.events = keep;
        removed
    }

    fn busiest(&self) -> Option<u32> {
        let mut best: Option<(u32, usize)> = None;
        for (&t, names) in &self.events {
            if best.map_or(true, |(_, n)| names.len() > n) {
                best = Some((t, names.len()));
            }
        }
        best.map(|(t, _)| t)
    }
}

unitTests:
fn sample() -> Timeline {
    let mut t = Timeline::new();
    t.add(540, "standup");
    t.add(720, "lunch");
    t.add(540, "coffee");
    t.add(900, "review");
    t.add(1080, "dinner");
    t
}

test("between keeps time order and adding order", || {
    let t = sample();
    check_eq(t.between(500, 800), vec![(540, "standup".to_string()), (540, "coffee".to_string()), (720, "lunch".to_string())]);
    check_eq(t.between(720, 720), Vec::<(u32, String)>::new());
    check_eq(t.between(900, 901), vec![(900, "review".to_string())]);
});

test("next after", || {
    let t = sample();
    check_eq(t.next_after(540), Some((720, "lunch".to_string())));
    check_eq(t.next_after(0), Some((540, "standup".to_string())));
    check_eq(t.next_after(1080), None);
});

test("remove before", || {
    let mut t = sample();
    check_eq(t.remove_before(720), 2);
    check_eq(t.between(0, 2000).len(), 3);
    check_eq(t.remove_before(0), 0);
});

test("busiest", || {
    let mut t = sample();
    check_eq(t.busiest(), Some(540));
    t.add(900, "demo");
    check_eq(t.busiest(), Some(540));
    check_eq(Timeline::new().busiest(), None);
});

